#!/usr/bin/env node
/**
 * Backlink Verification Script
 * Runs on GitHub Actions weekly to scan major platforms for backlinks to immaculate.tr
 * Reads sources from public/data/sources.json (generated by generate-sources.cjs)
 * Writes results to public/data/results.json — consumed by the static GitHub Pages site
 */

const fs = require("fs");
const path = require("path");

const TARGET_DOMAIN = "immaculate.tr";

// Load sources from the generated JSON file — single source of truth
const sourcesPath = path.join(__dirname, "..", "public", "data", "sources.json");
const SOURCES = JSON.parse(fs.readFileSync(sourcesPath, "utf8"));

function extractTitle(html) {
  const m = html.match(/<title[^>]*>([^<]+)<\/title>/i);
  return m && m[1] ? m[1].trim().substring(0, 200) : null;
}

function findBacklink(text, pattern) {
  try {
    const regex = new RegExp(pattern, "i");
    if (regex.test(text)) {
      const urlMatch = text.match(new RegExp("https?://[^\\s\"'<>]*" + pattern, "i"));
      if (urlMatch) return { url: urlMatch[0], anchorText: "" };
    }
    return null;
  } catch {
    return null;
  }
}

async function verifySource(source) {
  const startTime = Date.now();
  const query = encodeURIComponent(TARGET_DOMAIN);
  const searchUrl = source.search_url_template.replace("{query}", query);

  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 20000);

    const response = await fetch(searchUrl, {
      headers: {
        "User-Agent": "Mozilla/5.0 (compatible; BacklinkVerifier/1.0; +https://immaculate.tr)",
        Accept: "text/html,application/json,*/*",
        "Accept-Language": "en-US,en;q=0.9,tr;q=0.8",
      },
      signal: controller.signal,
      redirect: "follow",
    });

    clearTimeout(timeoutId);
    const elapsed = Date.now() - startTime;

    if (!response.ok && response.status !== 302) {
      return {
        source_id: source.id, source_name: source.name, status: "error",
        found_url: null, http_status: response.status, response_time_ms: elapsed,
        page_title: null, anchor_text: null, error_message: "HTTP " + response.status,
      };
    }

    const contentType = response.headers.get("content-type") || "";
    const bodyText = await response.text();
    let found = null;
    let pageTitle = null;

    if (contentType.includes("application/json")) {
      try {
        const json = JSON.parse(bodyText);
        const jsonStr = JSON.stringify(json);
        pageTitle = json.title || json.response?.docs?.[0]?.title || null;
        found = findBacklink(jsonStr, source.verify_url_pattern);
      } catch { /* not JSON */ }
    } else {
      pageTitle = extractTitle(bodyText);
      found = findBacklink(bodyText, source.verify_url_pattern);
    }

    return {
      source_id: source.id, source_name: source.name,
      status: found ? "verified" : "not_found",
      found_url: found ? found.url : null,
      http_status: response.status, response_time_ms: elapsed,
      page_title: pageTitle, anchor_text: found ? found.anchorText : null,
      error_message: null,
    };
  } catch (err) {
    const elapsed = Date.now() - startTime;
    const msg = err.name === "AbortError" ? "Request timed out (20s)" : (err.message || "Unknown error");
    return {
      source_id: source.id, source_name: source.name, status: "error",
      found_url: null, http_status: null, response_time_ms: elapsed,
      page_title: null, anchor_text: null, error_message: msg,
    };
  }
}

async function main() {
  console.log("Starting backlink verification for " + TARGET_DOMAIN);
  console.log("Sources: " + SOURCES.length);

  const activeSources = SOURCES.filter(s => s.is_active);
  const concurrencyLimit = 10;
  const results = [];

  for (let i = 0; i < activeSources.length; i += concurrencyLimit) {
    const batch = activeSources.slice(i, i + concurrencyLimit);
    console.log("Batch " + (Math.floor(i / concurrencyLimit) + 1) + "/" + Math.ceil(activeSources.length / concurrencyLimit) + ": " + batch.map(b => b.name).join(", "));
    const batchResults = await Promise.all(batch.map(src => verifySource(src)));
    results.push(...batchResults);
  }

  const verified = results.filter(r => r.status === "verified");
  const notFound = results.filter(r => r.status === "not_found");
  const errors = results.filter(r => r.status === "error");

  const now = new Date().toISOString();

  const output = {
    target_domain: TARGET_DOMAIN,
    total_sources: results.length,
    verified: verified.length,
    not_found: notFound.length,
    errors: errors.length,
    results: results,
    sources: SOURCES,
    checked_at: now,
    history: [now],
  };

  const existingPath = path.join(__dirname, "..", "public", "data", "results.json");
  try {
    const existing = JSON.parse(fs.readFileSync(existingPath, "utf8"));
    if (existing.history && Array.isArray(existing.history)) {
      output.history = [...existing.history, now].slice(-52);
    }
  } catch { /* no existing file */ }

  const outPath = path.join(__dirname, "..", "public", "data", "results.json");
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, JSON.stringify(output, null, 2));

  console.log("\n=== RESULTS ===");
  console.log("Verified: " + verified.length);
  console.log("Not found: " + notFound.length);
  console.log("Errors: " + errors.length);
  console.log("Total: " + results.length);
  console.log("Written to: " + outPath);
}

main().catch(err => {
  console.error("Fatal error:", err);
  process.exit(1);
});
